-- /scanned build — ONE read-only capture (2026-08-24), consumed by the renderer fixture.
-- Never re-run to re-read. Days: 2026-08-24 (first full-funnel day) + 2026-08-07 (busy day).
COPY (SELECT 'scan' AS q, scan_date, ticker, gap_pct, prev_close, rel_volume, filter_reason, ep_score, score_tier, catalyst_quality, adv, pm_rvol, rank_by_gap FROM (SELECT DISTINCT ON (scan_date, ticker) scan_date, ticker, gap_pct, prev_close, rel_volume, filter_reason, ep_score, score_tier, catalyst_quality, adv, pm_rvol, rank_by_gap FROM mi_ep_scan_log WHERE scan_date IN ('2026-08-24','2026-08-07') ORDER BY scan_date, ticker, scan_time_et DESC NULLS LAST, id DESC) t ORDER BY scan_date, ticker) TO STDOUT WITH (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT 'graded' AS q, scan_date, ticker, live_tier, live_ep_score, live_quality_last, gap_pct_last, adv_dollar, live_side FROM mi_catalyst_tier_shadow WHERE scan_date IN ('2026-08-24','2026-08-07') ORDER BY scan_date, ticker) TO STDOUT WITH (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT 'alert' AS q, alert_date, ticker, ep_score, score_tier, gap_pct, catalyst_quality FROM (SELECT DISTINCT ON (alert_date, ticker) alert_date, ticker, ep_score, score_tier, gap_pct, catalyst_quality FROM mi_ep_alerts WHERE alert_date IN ('2026-08-24','2026-08-07') AND COALESCE(source,'live')='live' ORDER BY alert_date, ticker, created_at DESC) t) TO STDOUT WITH (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT 'trade' AS q, alert_date, ticker, status, skip_reason, total_pnl, account_mode FROM mi_live_trades WHERE alert_date IN ('2026-08-24','2026-08-07') ORDER BY alert_date, ticker) TO STDOUT WITH (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT 'outcome' AS q, alert_date, ticker, skip_category, ret_1d, ret_5d, max_high_5d, last_refreshed_at FROM mi_ep_missed_outcomes WHERE alert_date IN ('2026-08-24','2026-08-07') ORDER BY alert_date, ticker) TO STDOUT WITH (FORMAT csv, DELIMITER E'\t', HEADER true);
